status.css:
:host{container-type:inline-size}*,*::before,*::after{box-sizing:border-box}[role="meter"]{min-width:0}[role="meter"]>i,[role="meter"]>.mw-fill{width:0}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
.mw-card{position:relative;isolation:isolate;width:100%;padding:0 19px 22px;font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;color:#e1e2d9;background:radial-gradient(ellipse at 90% 4%,#7a806715,transparent 65%),linear-gradient(150deg,#262e2e,#171e20 65%);border:1px solid #6e736260;border-top:2px solid #a79a75;border-radius:1px;line-height:1.8;overflow:hidden;overflow-wrap:anywhere;box-shadow:inset 0 0 45px #00000020}
.mw-card::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;opacity:.25;background:radial-gradient(ellipse at 15% 25%,#d3d6be0f,transparent 70%)}
.mw-header{position:relative;isolation:isolate;display:flex;align-items:flex-start;gap:12px;padding:21px 0 20px;margin-bottom:2px}.mw-header::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;transform-origin:left;background:linear-gradient(90deg,#a49b7e88,#a49b7e11);clip-path:polygon(0 25%,15% 0,40% 30%,68% 15%,100% 55%,87% 85%,44% 70%,20% 100%,0 80%);pointer-events:none}.mw-landscape{position:absolute;left:-16px;right:auto;bottom:0;width:calc(100% + 32px);height:130px;z-index:-1;pointer-events:none;opacity:.55}.mw-titleblock{flex:1;min-width:0}.mw-kicker{display:flex;align-items:baseline;gap:10px;font-size:11px;color:#c2b58e;letter-spacing:.1em}.mw-kicker span{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:9px;color:#949c91;letter-spacing:.12em}.mw-nm{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:31px;font-weight:400;line-height:1.5;letter-spacing:.08em;color:#f0efe3;margin:12px 0 3px;text-shadow:0 2px 12px #00000044}.mw-rel{font-size:11px;color:#aeb2a1;line-height:1.8}.mw-rel:empty{display:none}.mw-seal{flex:none;display:grid;place-items:center;margin-top:25px;width:27px;height:34px;border:1px solid #aa6b5977;outline:1px solid #aa6b5922;outline-offset:3px;color:#b98a73;font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:21px;line-height:1;transform:rotate(-4deg);background:#7e3d2917}
.mw-entry{display:grid;grid-template-columns:47px minmax(0,1fr);gap:15px;align-items:start;padding:12px 0;border-bottom:1px solid #8c917b22}.mw-lab{font-size:11px;color:#b5b7a7;line-height:1.5;padding-top:2px}.mw-lab small{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:9px;letter-spacing:.12em;display:block;color:#7f897c;margin-top:4px}.mw-val{font-size:12px;line-height:1.95;color:#e0e1d5;min-width:0}.mw-plan .mw-val{color:#d1c39b}.mw-bag .mw-val{font-size:11px;color:#b4bdad}
.mw-aff{padding-top:15px;margin-top:1px}.mw-affhead{display:flex;align-items:baseline;justify-content:space-between;gap:12px;color:#aab2a1;font-size:11px}.mw-affhead>span>small{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:12px;margin-left:7px;color:#8c957f}.mw-affhead strong{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:28px;line-height:1.2;font-weight:400;color:#d9c89b;font-variant-numeric:tabular-nums}.mw-affhead strong small{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:10px;color:#8b9689}.mw-bar{height:3px;margin-top:13px;background:#77836932;overflow:hidden}.mw-fill{display:block;height:100%;background:linear-gradient(90deg,#827e60,#d6c595);transform-origin:left}
@keyframes mw-ink-draw{from{transform:scaleX(0);opacity:.2}to{transform:scaleX(1);opacity:1}}@keyframes mw-reveal{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}@keyframes mw-stamp{from{opacity:0;transform:translateY(-3px) rotate(-8deg) scale(1.12)}to{opacity:1;transform:rotate(-4deg) scale(1)}}@keyframes mw-mist{0%,100%{opacity:.2}50%{opacity:.75}}
@media(prefers-reduced-motion:no-preference){.mw-card::after{animation:mw-mist 12s ease-in-out infinite}.mw-seal{animation:mw-stamp .65s .1s ease-out both}.mw-header::after,.mw-fill{animation:mw-ink-draw 1.05s .1s ease-out both}.mw-titleblock,.mw-entry{animation:mw-reveal .6s .08s ease-out both}.mw-entry:nth-of-type(2){animation-delay:.14s}.mw-entry:nth-of-type(3){animation-delay:.2s}.mw-entry:nth-of-type(4){animation-delay:.26s}}
@container(max-width:280px){.mw-card{padding:0 16px 20px}.mw-nm{font-size:28px}.mw-entry{grid-template-columns:43px minmax(0,1fr);gap:11px}.mw-header{padding-top:18px}.mw-landscape{right:auto;opacity:.55}.mw-seal{width:24px;height:31px;font-size:19px}}

