:host{container-type:inline-size}*,*::before,*::after{box-sizing:border-box}[role="meter"]{min-width:0}[role="meter"]>i,[role="meter"]>.mw-fill{width:0}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}
.mw-scene{width:100%;font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;color:#d5dbcd;background:linear-gradient(145deg,#252e2d,#192123);border:1px solid #6e736260;border-radius:1px;padding:0 16px 20px;overflow:hidden;line-height:1.9}.mw-shead{position:relative;isolation:isolate;padding:16px 0 14px;border-bottom:1px solid #91967c33}.mw-landscape{position:absolute;left:-16px;right:auto;bottom:0;width:calc(100% + 32px);height:120px;z-index:-1;pointer-events:none;opacity:.55}.mw-slabel{display:flex;gap:10px;align-items:baseline;font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:10px;color:#bdb28f;letter-spacing:.1em}.mw-slabel span{font-family:"Malgun Gothic","맑은 고딕","Apple SD Gothic Neo",system-ui,sans-serif;font-size:9px;letter-spacing:0;color:#8e9b89}.mw-splace{font-family:"Batang","바탕","Noto Serif KR","AppleMyungjo",Georgia,serif;font-size:22px;line-height:1.6;font-weight:400;letter-spacing:.03em;color:#ececde;margin:9px 0 4px}.mw-stime{font-size:10px;color:#a3ad98}.mw-desc{font-size:12px;line-height:2.05;color:#c7d0be;margin:14px 0 0;overflow-wrap:anywhere}.mw-motion{margin-top:15px;padding-top:12px;border-top:1px solid #8b95782b}.mw-motion>span{font-size:9px;color:#b6aa82;letter-spacing:.08em}.mw-motion p{font-size:11px;color:#9faa94;line-height:1.95;margin:6px 0 0;overflow-wrap:anywhere}
@keyframes mw-scene-ink{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}@media(prefers-reduced-motion:no-preference){.mw-splace{animation:mw-scene-ink .6s ease-out both}.mw-desc{animation:mw-scene-ink .65s .1s ease-out both}.mw-motion{animation:mw-scene-ink .65s .2s ease-out both}}

